/**
 * @fileoverview The host's own leaves (#714), mounted with `api.slothlet.api.add("host", …)` as rummage mounts its
 * `host.*` leaves: `records.apply` takes a caller's callback and asks for a store partition.
 * @module owner-host/leaves
 */

/**
 * Build the leaves.
 * @param {() => object} getApi - The bound api the host's `slothlet()` call returned, once it exists.
 * @returns {object} The leaves.
 */
export function makeLeaves(getApi) {
	return {
		echo: (value) => `echo:${value}`,
		records: { apply: (callback) => (typeof callback === "function" ? getApi().store.partition("records") : null) }
	};
}
